function separateSelected(){const o=item(),node=o&&objects.get(o.id);const collision=layoutObservation?.collisions?.find(c=>c.a===o?.id||c.b===o?.id);if(!o||!node||!collision||busy||previewOnly||['light','plane'].includes(o.kind)){banner('当前没有可处理的已保存重叠');return}const otherId=collision.a===o.id?collision.b:collision.a,other=objects.get(otherId);if(!other){banner('重叠对象尚未载入，无法计算移开方向');return}node.updateWorldMatrix(true,true);other.updateWorldMatrix(true,true);const box=new T.Box3().setFromObject(node),otherBox=new T.Box3().setFromObject(other);if(box.isEmpty()||otherBox.isEmpty()){banner('当前对象边界不可用，请人工调整');return}const overlap=[Math.min(box.max.x,otherBox.max.x)-Math.max(box.min.x,otherBox.min.x),Math.min(box.max.y,otherBox.max.y)-Math.max(box.min.y,otherBox.min.y),Math.min(box.max.z,otherBox.max.z)-Math.max(box.min.z,otherBox.min.z)];const valid=overlap.map((value,index)=>Number.isFinite(value)&&value>0?value:Infinity);const axis=valid.indexOf(Math.min(...valid));if(axis<0||!Number.isFinite(valid[axis])){banner('当前边界已无重叠，请保存后重新核对');return}const names=['x','y','z'],axisName=names[axis],center=box.getCenter(new T.Vector3()),otherCenter=otherBox.getCenter(new T.Vector3()),direction=center[axisName]>=otherCenter[axisName]?1:-1;const next=o.position.map(Number);next[axis]+=direction*(valid[axis]+.05);if(next.some(value=>!Number.isFinite(value)||Math.abs(value)>100)){banner('移开结果超出场景范围，请使用右侧数值调整');return}checkpoint();o.position=next;configure(o,node);select(o.id,true);paint();banner(`已沿 ${axisName.toUpperCase()} 轴移开重叠 · 可撤销 · 保存后重新核对`)}
$('separateOverlap').onclick=()=>separateSelected();
